<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account — {{ config('platform.name') }}</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:#17233c;font-family:Inter,Arial,sans-serif}.auth-page{min-height:calc(100vh - 72px);display:flex;background:radial-gradient(circle at 20% 20%,rgba(43,103,201,.08),transparent 35%),#f6f8fc}.brand-panel{position:relative;display:flex;justify-content:center;flex-direction:column;overflow:hidden;width:52%;padding:70px 7%;background:radial-gradient(circle at 85% 20%,rgba(64,123,255,.35),transparent 30%),linear-gradient(135deg,#101d33,#172b4d 55%,#203d70);color:#fff}.brand-panel:before,.brand-panel:after{content:"";position:absolute;border:1px solid #ffffff14;border-radius:50%}.brand-panel:before{width:450px;height:450px;right:-170px;top:-150px}.brand-panel:after{width:280px;height:280px;left:-120px;bottom:-100px}.brand-content{position:relative;z-index:1;max-width:590px}.welcome{display:inline-flex;padding:9px 14px;border:1px solid #ffffff22;border-radius:30px;background:#ffffff16;font-size:12px;font-weight:700}.brand-title{margin:27px 0 18px;font-size:clamp(38px,4vw,50px);line-height:1.12;letter-spacing:-1.7px}.brand-title span{color:#73a7ff}.brand-copy{max-width:530px;color:#ffffffb8;line-height:1.8}.benefits{display:grid;gap:13px;margin:32px 0}.benefit{display:flex;align-items:center;gap:12px;font-size:14px;color:#ffffffe0}.check{display:grid;place-items:center;width:34px;height:34px;border:1px solid #78a8ff2e;border-radius:10px;background:#639aff29;color:#8cb8ff}.stats{display:flex;gap:32px;padding-top:25px;border-top:1px solid #ffffff1f}.stat strong{display:block;font-size:23px}.stat span{color:#ffffff8c;font-size:11px}.form-panel{display:flex;align-items:center;justify-content:center;width:48%;padding:45px 30px}.auth-card{width:100%;max-width:480px}.auth-heading h1{margin:0 0 8px;font-size:32px}.auth-heading p{margin:0 0 26px;color:#7b879a;font-size:14px;line-height:1.6}.error-summary{margin-bottom:18px;padding:12px;border-radius:8px;background:#fff1f2;color:#b42318;font-size:13px}.group{margin-bottom:16px}.label{display:block;margin-bottom:7px;font-size:13px;font-weight:700}.input-wrap{position:relative}.input-icon{position:absolute;left:15px;top:50%;transform:translateY(-50%);color:#93a0b4}.control{width:100%;height:51px;padding:0 48px 0 44px;border:1px solid #dce3ed;border-radius:10px;outline:0;background:#fff;color:#17233c}.control:focus{border-color:#3777e8;box-shadow:0 0 0 4px #3777e81a}.toggle{position:absolute;right:13px;top:50%;transform:translateY(-50%);border:0;background:transparent;color:#65728a;cursor:pointer}.field-error{margin-top:5px;color:#dc3545;font-size:11px}.strength{display:none;margin-top:8px}.bars{display:flex;gap:5px}.bar{height:4px;flex:1;border-radius:10px;background:#e7ebf1}.strength-text{margin-top:6px;color:#8a96a8;font-size:11px}.terms{display:flex;align-items:flex-start;gap:8px;margin:18px 0;color:#7c8798;font-size:12px;line-height:1.5}.terms input{margin-top:3px;accent-color:#2865d9}.terms a,.login a{color:#2865d9;font-weight:700}.submit{width:100%;height:53px;border:0;border-radius:10px;background:linear-gradient(135deg,#245bc6,#3779e8);color:#fff;font-weight:700;cursor:pointer;box-shadow:0 10px 22px #2d66d338}.submit:hover{transform:translateY(-1px)}.login{margin-top:22px;text-align:center;color:#7b8798;font-size:13px}.home-link{display:block;margin-top:13px;text-align:center;color:#65728a;font-size:12px}@media(max-width:950px){.brand-panel{display:none}.form-panel{width:100%;min-height:calc(100vh - 72px)}}@media(max-width:600px){.form-panel{padding:32px 20px}.auth-heading h1{font-size:27px}}</style></head><body><main class="auth-page"><section class="brand-panel"><div class="brand-content"><span class="welcome">✦ {{ strtoupper(config('platform.name')) }} CAREER PLATFORM</span><h2 class="brand-title">Launch your <span>engineering career</span> with confidence.</h2><p class="brand-copy">Discover verified opportunities, improve your skills and build the career you want through one connected platform.</p><div class="benefits">@foreach(config('platform.benefits',[]) as $benefit)<div class="benefit"><span class="check">✓</span><span>{{ $benefit }}</span></div>@endforeach</div><div class="stats"><div class="stat"><strong>{{ number_format($stats['jobs']) }}</strong><span>Active opportunities</span></div><div class="stat"><strong>{{ number_format($stats['companies']) }}</strong><span>Companies hiring</span></div><div class="stat"><strong>{{ number_format($stats['remote']) }}</strong><span>Remote jobs</span></div></div></div></section><section class="form-panel"><div class="auth-card"><div class="auth-heading"><h1>Create your account</h1><p>Register securely, verify your email with an OTP, and start your career journey.</p></div>@if($errors->any())<div class="error-summary">Please correct the highlighted fields.</div>@endif<form method="post" action="{{ route('register.store') }}">@csrf<div class="group"><label class="label" for="name">Full name</label><div class="input-wrap"><span class="input-icon">●</span><input class="control" id="name" name="name" value="{{ old('name') }}" autocomplete="name" placeholder="Enter your full name" required autofocus></div>@error('name')<div class="field-error">{{ $message }}</div>@enderror</div><div class="group"><label class="label" for="email">Email address</label><div class="input-wrap"><span class="input-icon">@</span><input class="control" id="email" type="email" name="email" value="{{ old('email') }}" autocomplete="email" placeholder="you@example.com" required></div>@error('email')<div class="field-error">{{ $message }}</div>@enderror</div><div class="group"><label class="label" for="password">Create password</label><div class="input-wrap"><span class="input-icon">◆</span><input class="control" id="password" type="password" name="password" autocomplete="new-password" placeholder="At least 8 characters" required><button class="toggle" type="button" data-toggle="password">Show</button></div><div class="strength" id="strength"><div class="bars">@for($i=0;$i<4;$i++)<span class="bar"></span>@endfor</div><div class="strength-text" id="strength-text">Password strength</div></div>@error('password')<div class="field-error">{{ $message }}</div>@enderror</div><div class="group"><label class="label" for="password_confirmation">Confirm password</label><div class="input-wrap"><span class="input-icon">◆</span><input class="control" id="password_confirmation" type="password" name="password_confirmation" autocomplete="new-password" placeholder="Confirm your password" required><button class="toggle" type="button" data-toggle="password_confirmation">Show</button></div></div><label class="terms"><input type="checkbox" required><span>I agree to responsible use of the platform and acknowledge the <a href="{{ route('about') }}">platform information</a>.</span></label><button class="submit" type="submit">Send verification code →</button></form><div class="login">Already have an account?<a href="{{ route('login') }}"> Login</a></div><a class="home-link" href="{{ route('home') }}">← Return to job search</a></div></section></main><script>document.querySelectorAll('[data-toggle]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.toggle);input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'Show':'Hide'}));const password=document.getElementById('password'),strength=document.getElementById('strength'),bars=[...document.querySelectorAll('.bar')],strengthText=document.getElementById('strength-text');password.addEventListener('input',()=>{if(!password.value){strength.style.display='none';return}strength.style.display='block';let score=0;if(password.value.length>=8)score++;if(/[A-Z]/.test(password.value))score++;if(/[0-9]/.test(password.value))score++;if(/[^A-Za-z0-9]/.test(password.value))score++;bars.forEach((bar,index)=>bar.style.background=index<score?'#3779e8':'#e7ebf1');strengthText.textContent=['Weak password','Weak password','Fair password','Good password','Strong password'][score]});</script></body></html>
